import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"WebDAV Module","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/modules/webdav.md","filePath":"en/deep-dive/modules/webdav.md","lastUpdated":1785793343000}`),a={name:`deep-dive/modules/webdav.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="webdav-module" tabindex="-1">WebDAV Module <a class="header-anchor" href="#webdav-module" aria-label="Permalink to “WebDAV Module”">​</a></h1><p>The WebDAV module registers the <code>webdav</code> remote file system. It implements the <a href="./../file-system#unified-key-schema">unified file-system key schema</a> using only Sync Engine&#39;s injected <a href="./../request"><code>Request</code></a> abstraction; it has no WebDAV client dependency.</p><p>Every request uses HTTP Basic authentication. The module normalizes the endpoint and percent-encodes individual remote path segments before issuing a request.</p><h2 id="supported-backends" tabindex="-1">Supported Backends <a class="header-anchor" href="#supported-backends" aria-label="Permalink to “Supported Backends”">​</a></h2><p>The standard mode can theoretically work with any WebDAV service that supports HTTP(S), Basic authentication, ranged <code>GET</code>, <code>PROPFIND</code>, <code>PUT</code>, <code>DELETE</code>, <code>MOVE</code>, and <code>MKCOL</code>. This includes WebDAV installations based on:</p><ul><li>Nextcloud</li><li>ownCloud</li><li>Apache <code>mod_dav</code></li><li>Microsoft IIS WebDAV</li><li>InfiniCloud</li><li>Koofr WebDAV API</li><li>Synology WebDAV Server</li><li>Seafile&#39;s WebDAV extension</li><li>SabreDAV</li><li>Nutstore</li><li>AList, OpenList, and Cloudreve&#39;s WebDAV compatibility layer</li></ul><p>The optional chunked-upload mode requires Nextcloud&#39;s upload protocol and is not standard WebDAV. Enable it only for compatible Nextcloud servers.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h2><p>The module registers these settings:</p><ul><li><strong>Server URL</strong>: HTTP or HTTPS WebDAV endpoint. Invalid URLs and non-HTTP(S) protocols are rejected; trailing slashes are removed when saved.</li><li><strong>Username</strong>: WebDAV account name, trimmed before saving.</li><li><strong>Password</strong>: WebDAV account password. Obsidian stores it in its keychain rather than module settings.</li><li><strong>Base directory</strong>: Remote directory that becomes the vault root. <code>/</code> uses the endpoint root. Values are trimmed and normalized with a trailing slash. An empty persisted value defaults to <code>&lt;vault name&gt;/</code> when the module is constructed.</li><li><strong>Use <code>Depth: infinity</code></strong>: Lists a directory tree with one <code>PROPFIND</code> request instead of recursively traversing depth-one responses. It can speed remote discovery, but some servers do not support it. It gives no performance benefit with <a href="./../asymmetric-storage">asymmetric storage</a> enabled.</li><li><strong>Nextcloud-style chunked upload</strong>: Uploads large streamed files through Nextcloud&#39;s chunked-upload protocol rather than buffering each whole file in memory. Most WebDAV servers do not support this mode.</li></ul><h2 id="file-operations" tabindex="-1">File Operations <a class="header-anchor" href="#file-operations" aria-label="Permalink to “File Operations”">​</a></h2><p><code>read()</code> sends <code>GET</code> and returns response bytes. <code>write()</code> sends <code>PUT</code>, returning its <code>ETag</code> header when present; otherwise it immediately calls <code>stat()</code> and returns the resulting file UID.</p><p><code>delete()</code> sends <code>DELETE</code> and treats HTTP <code>404</code> as already deleted. <code>move()</code> sends <code>MOVE</code> with a <code>Destination</code> header. <code>mkdir()</code> sends <code>MKCOL</code>; recursive creation creates ancestor directories in order and ignores HTTP <code>405</code>, which indicates an existing directory.</p><p><code>stat()</code> sends a depth-zero <code>PROPFIND</code> for the target, except <code>/</code>, which is returned locally as a folder. The request asks for the resource type, modification time, content length, and <code>ETag</code>. File UIDs use <code>ETag</code> when available, otherwise <code>&lt;mtime&gt;~&lt;size&gt;</code>; folders have no UID. <code>exists()</code> uses the same lookup and returns <code>false</code> for HTTP <code>404</code>.</p><p><code>PROPFIND</code> response pagination is supported through a <code>Link: &lt;...&gt;; rel=&quot;next&quot;</code> response header.</p><h2 id="streaming" tabindex="-1">Streaming <a class="header-anchor" href="#streaming" aria-label="Permalink to “Streaming”">​</a></h2><p><code>readStream()</code> uses ranged <code>GET</code> requests because <a href="./../request#limitations"><code>Request</code> cannot expose a response stream</a>. It requests 2 MiB ranges, keeps at most eight requests in flight, buffers at most eight chunks, and emits chunks in source order. New requests are scheduled only while the stream consumer can accept data. A zero-byte file returns a closed stream.</p><p>Without chunked upload, <code>writeStream()</code> collects the complete input stream in memory, then calls <code>write()</code>.</p><p>With Nextcloud-style chunked upload enabled, it:</p><ol><li>Creates a UUID-named upload collection under Nextcloud&#39;s upload endpoint.</li><li>Splits the input into 5 MiB numbered chunks and uploads at most three concurrently. Each upload includes <code>Destination</code> and <code>OC-Total-Length</code> headers.</li><li>Moves the generated <code>.file</code> to the destination.</li><li>Returns <code>ETag</code> or <code>OC-ETag</code>; when neither is present, it calls <code>stat()</code> for the file UID.</li></ol><p>On failure, the module waits for active uploads and deletes the temporary upload collection.</p><h2 id="base-directory-wrapper" tabindex="-1">Base Directory Wrapper <a class="header-anchor" href="#base-directory-wrapper" aria-label="Permalink to “Base Directory Wrapper”">​</a></h2><p>WebDAV uses the shared importable <a href="./../../development/file-system#prefixwrapper"><code>prefixWrapper</code></a> to expose its configured base directory as the file-system root. See <a href="./../file-system-wrappers">file-system wrappers</a> for wrapper-chain details.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};